{"code":"import pathlib, re

root = pathlib.Path('servisler')
for p in sorted(root.rglob('*.ini')):
    data = p.read_bytes()
    print('==', p, '| BOM:', data.startswith(b'\xef\xbb\xbf'), '| CRLF count:', data.count(b'\r\n'), 'LF-only:', data.count(b'\n') - data.count(b'\r\n'))
    for i, line in enumerate(data.decode('utf-8-sig').split('\n'), 1):
        print(f'{i:3} {line!r}')
